const body = $input.first().json.body ?? $input.first().json;

const externalId = body.external_id;
const newText = body.new_text;
const messageId = body.message_id;
const phoneRaw = body.phone ?? '';

if (!externalId || !newText) {
  return [{ json: { ok: false, message: 'external_id ou new_text ausente' } }];
}

// chatId no formato do WAHA. Se o proprio ID composto ja traz o chat
// (ex.: "true_5511999@c.us_3EB0..." ou "true_8186@lid_3EB0..."), usamos ele:
// e o endereco exato com que o WhatsApp conhece essa conversa, inclusive quando
// e um @lid. Caso contrario caimos no telefone do contato.
let chatId = null;
const parts = String(externalId).split('_');
if (parts.length >= 3 && parts[1].includes('@')) {
  chatId = parts[1];
} else {
  const digits = String(phoneRaw).replace(/\D/g, '');
  if (digits) chatId = `${digits}@c.us`;
}

if (!chatId) {
  return [{ json: { ok: false, message: 'nao foi possivel determinar o chat da mensagem' } }];
}

return [{
  json: {
    ok: true,
    session: 'crmobesity',
    chat_id: chatId,
    message_id: messageId,
    external_id: String(externalId),
    new_text: String(newText)
  }
}];

const resp = $input.first().json;
const status = resp.statusCode ?? 0;
const payload = resp.body ?? resp;

if (status >= 200 && status < 300) {
  return [{ json: { success: true, message: 'Mensagem editada no WhatsApp' } }];
}

// O WAHA responde 4xx/5xx quando o motor da sessao nao implementa edicao
// ("The method is not implemented by the engine") ou quando a mensagem e
// antiga demais — o WhatsApp so permite editar ate ~15 minutos apos o envio.
let detail = '';
if (typeof payload === 'string') detail = payload;
else detail = payload?.message || payload?.error || JSON.stringify(payload || {});

let friendly = `WhatsApp recusou (HTTP ${status})`;
if (/not implemented|unsupported|nao implementad/i.test(detail)) {
  friendly = 'o motor atual do WhatsApp (WAHA) nao suporta edicao';
} else if (/too old|15 min|expired|timeout/i.test(detail)) {
  friendly = 'a mensagem e antiga demais (o WhatsApp so deixa editar por ~15 minutos)';
} else if (detail) {
  friendly = `WhatsApp recusou: ${String(detail).slice(0, 200)}`;
}

return [{ json: { success: false, message: friendly, http_status: status, raw: String(detail).slice(0, 500) } }];
